import{_ as a,c as n,o as s,ag as t}from"./chunks/framework.Ci10AEOF.js";const u=JSON.parse('{"title":"Installing Open Integration Engine","description":"System requirements, choosing an installer, and installing on Windows, macOS and Linux","frontmatter":{"title":"Installing Open Integration Engine","description":"System requirements, choosing an installer, and installing on Windows, macOS and Linux"},"headers":[],"relativePath":"engine/installation.md","filePath":"engine/installation.md","lastUpdated":1793057853000}'),i={name:"engine/installation.md"};function r(o,e,l,c,p,d){return s(),n("div",null,e[0]||(e[0]=[t(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Open Integration Engine™️, also called OIE™️ in this documentation, installs from a native installer on Windows, macOS and Linux.</p><h2 id="system-requirements" tabindex="-1">System requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System requirements&quot;">​</a></h2><p>The OIE Server operates as a self-contained application and does not depend on any external application server.</p><h3 id="java-requirements" tabindex="-1">Java requirements <a class="header-anchor" href="#java-requirements" aria-label="Permalink to &quot;Java requirements&quot;">​</a></h3><p>The server runs on Java 17 or newer. The With JRE installers bundle one; otherwise the machine needs it. The server starts with a 256 MB heap, set in <code>conf/base_includes.vmoptions</code>. See <a href="./server_configuration.html#jvm-options">JVM options</a> for raising it.</p><h3 id="database-requirements" tabindex="-1">Database requirements <a class="header-anchor" href="#database-requirements" aria-label="Permalink to &quot;Database requirements&quot;">​</a></h3><p>OIE stores configuration and messages in an embedded Apache Derby database by default.</p><div class="warning custom-block"><p class="custom-block-title">Derby is not recommended for production</p><p>Use one of the databases below for a production server. See <a href="./database_support.html">Database Support</a> for moving off Derby.</p></div><p>For production deployments, it is recommended to use only database versions currently receiving official security and maintenance support from their respective vendors. The following database engines are supported as backends:</p><ul><li>PostgreSQL</li><li>MySQL</li><li>Oracle 12c or newer</li><li>SQL Server</li></ul><p>These requirements govern only the database the server itself stores configuration and messages in. Channels can also read from and write to other databases through the Database Reader and Database Writer. See <a href="./database_support.html">Database Support</a> for changing the backing database and <a href="./connector_reference_sources.html#jdbc-drivers-and-url-templates">Connector Reference</a> for the channel-side drivers.</p><h2 id="download-and-installation" tabindex="-1">Download and installation <a class="header-anchor" href="#download-and-installation" aria-label="Permalink to &quot;Download and installation&quot;">​</a></h2><p>Every release publishes native installers for Windows, macOS and Linux on the <a href="https://github.com/OpenIntegrationEngine/engine/releases/latest" target="_blank" rel="noreferrer">releases page</a>, plus <code>.tar.gz</code> and <code>.zip</code> archives for Linux and Windows. The installer installs the application, registers OIE as a native service, and sets it to start on boot. If you would rather do it by hand, see <a href="#installing-from-an-archive">Installing from an archive</a>.</p><h3 id="choosing-an-installer" tabindex="-1">Choosing an installer <a class="header-anchor" href="#choosing-an-installer" aria-label="Permalink to &quot;Choosing an installer&quot;">​</a></h3><p>Each platform ships in two flavors.</p><p><strong>With JRE</strong> bundles Eclipse Temurin (Adoptium) JDK 21.0.12.1, so nothing else needs installing.</p><p><strong>Without JRE</strong> is smaller and uses a Java runtime already on the machine. The launchers the installer creates accept Java 17 and newer, with no upper limit. See <a href="./server_process_management.html#choosing-a-java">Choosing a Java</a> for how they find one. Choose it when Java is managed centrally or already hardened to a standard you have to meet.</p><p>The bundled flavor is about 63MB to 67MB larger depending on platform.</p><p>Pick the build that matches your architecture: <code>aarch</code> for Apple silicon and <code>x86</code> for Intel Macs, <code>x64</code> or <code>arm64</code> on Windows. Each release also publishes <code>sha256sums</code> and <code>md5sums</code>.</p><h3 id="installing" tabindex="-1">Installing <a class="header-anchor" href="#installing" aria-label="Permalink to &quot;Installing&quot;">​</a></h3><p>Open the file you downloaded:</p><ul><li><strong>Windows</strong>: run the <code>.exe</code>.</li><li><strong>macOS</strong>: mount the <code>.dmg</code> and launch the installer inside it.</li><li><strong>Linux</strong>: make the <code>.sh</code> executable with <code>chmod +x</code>, then run it.</li></ul><p>Then follow the wizard: accept the Mozilla Public License 2.0, choose an installation directory, and click <code>Finish</code>. The installer requires administrative rights, because registering a system service does.</p><p>On a headless machine the installer detects that no display is available and runs as a console installer instead.</p><div class="warning custom-block"><p class="custom-block-title">Your operating system will warn about the installer</p><p>Windows and macOS check downloaded programs for a code signature. The OIE installer does not have one, so you will see a security warning.</p><p>On Windows the warning comes from SmartScreen, and often from the browser as well. On macOS, Gatekeeper blocks the <code>.dmg</code> the first time you open it. Allow it under System Settings, Privacy &amp; Security. The wording varies by version.</p><p>The Administrator client jars and the bundled extension jars carry a signature from a certificate authority with a trusted timestamp. The server jars, the command line jars and the two launcher jars are not signed by the project.</p><p>Check your download against the published <code>sha256sums</code> and continue.</p></div><div class="warning custom-block"><p class="custom-block-title">Install directory and sudo</p><p>Installing into a directory you do not own, such as the default <code>/Applications/OpenIntegrationEngine</code> on macOS, means anything you later run by hand needs <code>sudo</code>.</p></div><h3 id="installing-from-an-archive" tabindex="-1">Installing from an archive <a class="header-anchor" href="#installing-from-an-archive" aria-label="Permalink to &quot;Installing from an archive&quot;">​</a></h3><p>The release also publishes <code>oie_unix_&lt;version&gt;.tar.gz</code> and <code>oie_windows-&lt;arch&gt;_&lt;version&gt;.zip</code> for a manual install. Unpack the archive wherever you want it and run <code>oieserver</code> (<code>oieserver.exe</code> on Windows) from the extracted directory. The archives carry no Java, so the machine needs Java 17 or newer. See <a href="./server_process_management.html#choosing-a-java">Choosing a Java</a>.</p><p>Nothing is registered with the service manager and nothing starts on boot, so you have to wire it into systemd, launchd or the Windows service manager yourself. This route also works when you cannot give an installer administrative rights.</p><h2 id="directory-layout" tabindex="-1">Directory layout <a class="header-anchor" href="#directory-layout" aria-label="Permalink to &quot;Directory layout&quot;">​</a></h2><p>After installation and the first start, the directory contains:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OIE_HOME/</span></span>
<span class="line"><span>├── appdata/                # Application data, created by the server on first start</span></span>
<span class="line"><span>│   ├── mirthdb/            # Embedded Derby database, when Derby is in use</span></span>
<span class="line"><span>│   ├── temp/               # java.io.tmpdir for the server, created at startup</span></span>
<span class="line"><span>│   ├── keystore.jks        # TLS keystore</span></span>
<span class="line"><span>│   ├── extension.properties        # Installed extension state</span></span>
<span class="line"><span>│   ├── server.id           # Unique server identifier</span></span>
<span class="line"><span>│   └── configuration.properties    # Configuration map, created at runtime</span></span>
<span class="line"><span>├── cli-lib/                # CLI libraries</span></span>
<span class="line"><span>├── client-lib/             # Administrator client libraries</span></span>
<span class="line"><span>├── conf/                   # Configuration files</span></span>
<span class="line"><span>│   ├── mirth.properties            # Main server configuration</span></span>
<span class="line"><span>│   ├── dbdrivers.xml               # Database driver definitions</span></span>
<span class="line"><span>│   ├── log4j2.properties           # Logging configuration</span></span>
<span class="line"><span>│   ├── log4j2-cli.properties       # CLI logging configuration</span></span>
<span class="line"><span>│   ├── mirth-cli-config.properties # CLI defaults</span></span>
<span class="line"><span>│   ├── base_includes.vmoptions     # Base JVM options, do not modify</span></span>
<span class="line"><span>│   ├── custom.vmoptions            # Your JVM options</span></span>
<span class="line"><span>│   └── default_modules.vmoptions   # Java module system options</span></span>
<span class="line"><span>├── docs/                   # Licenses and the user API javadocs</span></span>
<span class="line"><span>├── extensions/             # Connectors and plugins</span></span>
<span class="line"><span>├── logs/                   # Server log files</span></span>
<span class="line"><span>├── public_html/            # Web server root</span></span>
<span class="line"><span>├── public_api_html/        # REST API documentation</span></span>
<span class="line"><span>├── server-launcher-lib/    # Empty at install, jars placed here join the launcher classpath</span></span>
<span class="line"><span>├── server-lib/             # Server libraries</span></span>
<span class="line"><span>├── mirth-server-launcher.jar   # Server launcher JAR</span></span>
<span class="line"><span>├── mirth-cli-launcher.jar      # CLI launcher JAR</span></span>
<span class="line"><span>├── oiecommand              # CLI launcher</span></span>
<span class="line"><span>├── oieserver               # Server launcher, foreground</span></span>
<span class="line"><span>├── oieservice              # Service launcher, registered with the OS</span></span>
<span class="line"><span>├── oieserver.vmoptions     # JVM options for the foreground launcher</span></span>
<span class="line"><span>└── oieservice.vmoptions    # JVM options for the service</span></span></code></pre></div><p>It also holds others, such as <code>configure-from-env</code>, <code>uninstall</code>, a hidden <code>.install4j/</code> directory, <code>derby.log</code> when Derby is in use, and <code>appdata/exports/</code> after an events export.</p><p>Runtime-created directories such as <code>appdata/</code> are kept when the installer runs over an existing installation. See <a href="./upgrade_guide.html">Upgrade Guide</a> before doing that on a server you care about.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./server_process_management.html">Server Process Management</a> to start it.</li><li><a href="./accessing_the_administrator.html">Accessing the Administrator</a> to log in.</li><li><a href="./database_support.html">Database Support</a> to move off Derby before production.</li><li><a href="./migrating_from_mirth_connect.html">Migrating from Mirth Connect</a> if you are replacing an existing Mirth Connect server.</li></ul>`,37)]))}const m=a(i,[["render",r]]);export{u as __pageData,m as default};
